329			fake.mu.Lock()
330			fake.denyFeed = false
331			fake.denyPush = true
332			fake.mu.Unlock()
333			if _, err := f.call(binary, syncArgs...); err == nil {
334				t.Fatal("push failure was hidden")
335			}
336			if fake.has(pending.ID) {
337				t.Fatal("denied upload reached the server")
338			}
