func TestReclassifyAllFactBranches(t *testing.T) {
	now := time.Date(2026, 6, 16, 12, 0, 0, 0, time.UTC)
	brainDir := t.TempDir()

	// Facts on two branches with empty Kind (as in a store predating kind-storage).
	main := []factRecord{
