func newestLegacyOutlinePath(brainDir string) (string, error) {
	entries, err := os.ReadDir(filepath.Join(brainDir, factstore.DirName))
	if err != nil {
		if os.IsNotExist(err) {
			return "", nil
		}
		return "", err
	}
	var newest string
	var newestMod time.Time
	for _, entry := range entries {
