		if err := clibase.RejectExistingSymlinkPathComponents(brainDir, rel); err != nil {
			return "", err
		}
		path := filepath.Join(brainDir, rel)
		info, statErr := os.Stat(path)
		if statErr != nil || !info.Mode().IsRegular() {
			continue
		}
		if newest == "" || info.ModTime().After(newestMod) {
